/*
Trying to model persistance of vision as an average of all frames over time but with
exponentially decaying weight given to older frames. Without time scaling, a decay
factor of 500 seems to decently match my persistance of vision.
*/

#define TAU 6.283185

#define MOTION_BLUR
#define iTime (iTime * TIME_SCALE)

const float TIME_SCALE = 0.2;
const float MAJOR_RADIUS = 1.0;
const float MINOR_RADIUS = 0.25;
const float INITIAL_ANGLE = -TAU / 3.0;
const float ROTATIONAL_VELOCITY = -15.0;
const float DECAY = 100.0;

float circlingDisk(in vec2 p, in float t, in float R, in float r, in float theta0, in float omega, in float k) {
    float d = length(p);
    if (abs(d - R) > r) return 0.0;
    if (r > R && d < r - R) return 1.0;

    if (omega < 0.0) {
        p.y = -p.y;
        theta0 = -theta0;
        omega = -omega;
    }

    k /= omega;
    float theta1 = omega * t + theta0;

    float angle = atan(p.y, p.x);
    float angleOffset = acos((dot(p, p) + R * R - r * r) / (2.0 * R * d));
    float startAngle = angle - angleOffset;
    float endAngle = angle + angleOffset;

    float n0 = ceil((theta0 - endAngle) / TAU);
    float n1 = floor((theta1 - startAngle) / TAU);
    if (n1 < n0) return 0.0;

    if (n0 == n1) {
        float turn = TAU * n0;
        float a = max(theta0, startAngle + turn) - theta1;
        float b = min(theta1, endAngle + turn) - theta1;
        return exp(k * b) - exp(k * a);
    }

    float a, b;
    float accum = 0.0;
    float turn0 = TAU * n0;
    float turn1 = TAU * n1;

    a = max(theta0, startAngle + turn0) - theta1;
    b = endAngle + turn0 - theta1;
    accum += exp(k * b) - exp(k * a);

    a = startAngle + turn1 - theta1;
    b = min(theta1, endAngle + turn1) - theta1;
    accum += exp(k * b) - exp(k * a);

    a = startAngle - theta1;
    b = endAngle - theta1;
    float a0 = a + turn0, b0 = b + turn0;
    float a1 = a + turn1, b1 = b + turn1;
    accum += ((exp(k * (b1 - TAU)) - exp(k * (a1 - TAU))) - (exp(k * b0) - exp(k * a0))) / (1.0 - exp(-TAU * k));

    return accum;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 4.0;

    #ifdef MOTION_BLUR
    fragColor = vec4(circlingDisk(
        uv, iTime,
        MAJOR_RADIUS, MINOR_RADIUS,
        INITIAL_ANGLE, ROTATIONAL_VELOCITY,
        DECAY
    ));
    #else
    float a = iTime * ROTATIONAL_VELOCITY;
    fragColor = vec4(step(length(uv - vec2(cos(a), sin(a)) * MAJOR_RADIUS), MINOR_RADIUS));
    #endif

    fragColor.rgb = pow(fragColor.rgb, vec3(1.0 / 2.2));
}
